  insert into public.course_items (course_id, kind, position, title, content) select cid, 'topic', 1, $j$1.1 The Spanish Alphabet and Pronunciation$j$, $j${"readings": [{"title": "Genesis 11 (King James Version)", "url": "/portal/bible/Genesis/11"}], "body": "Spanish is spoken by more than 400 million people and is one of the most useful languages for ministry, work and community in Florida. The Bible tells us that God cares about every language. Genesis 11:9 records that the LORD did confound the language of all the earth, and today we learn another language so that we can bless our neighbors. Spanish is a very regular language, so once you learn the sounds you can read almost any word aloud.\n\nThe Spanish alphabet has 27 letters: the 26 letters of English plus the letter ñ. The five vowels always keep the same sound. A sounds like ah, E like eh, I like ee, O like oh and U like oo. Some consonants differ from English. The letter h is always silent, so hola sounds like OH lah. The letter j sounds like an English h, so jugo sounds like HOO go. The double l, ll, sounds like the English y, so llamo sounds like YAH mo. The ñ sounds like ny in canyon, so español sounds like es pah NYOL. The rr is rolled with the tongue. The letters b and v sound almost the same. The letter combination qu sounds like k, so queso sounds like KEH so. The letter g before e or i sounds like an English h, as in gente.\n\nSpanish words are stressed by rule. Words that end in a vowel, n or s are stressed on the next to last syllable. Other words are stressed on the last syllable. A written accent mark shows an exception, as in teléfono. Questions and exclamations begin with an upside down mark, as in ¿Cómo estás?\n\nYour task: (1) Say the five vowels aloud. (2) Pronounce hola, llamo, español, jugo and queso. (3) Explain what the accent mark shows.\n\nFlorida standards: WL.912.", "video": "", "presenter": "Dr. Alex L. Jenkins Sr.", "standards": "WL.912", "script": "Welcome back. Listen, Genesis 11:9 says the LORD did confound the language of all the earth. Today we learn another language so that we can bless our neighbors.\n\nNow watch this. The Spanish alphabet has 27 letters, the 26 you know plus ñ. The vowels never change. A is ah, E is eh, I is ee, O is oh and U is oo.\n\nThe letter h is silent, so hola is OH lah. The letter j sounds like an English h. The double l sounds like y, so llamo is YAH mo. The ñ sounds like ny, so español is es pah NYOL. The letters qu sound like k, as in queso.\n\nWords ending in a vowel, n or s are stressed on the next to last syllable. Other words are stressed on the last syllable. An accent mark shows the exception. Questions begin with an upside down question mark.\n\nYour task is to say the vowels, pronounce five words and explain the accent mark. Take the four question check. Excellence, Faith, Purpose. I will see you in the next lesson."}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'topic' and title = $j$1.1 The Spanish Alphabet and Pronunciation$j$);
  insert into public.course_items (course_id, kind, position, title, content) select cid, 'topic', 2, $j$1.2 Greetings, Farewells and Courtesy$j$, $j${"readings": [{"title": "Proverbs 15 (King James Version)", "url": "/portal/bible/Proverbs/15"}], "body": "Proverbs 15:1 says, A soft answer turneth away wrath: but grievous words stir up anger. Kind greetings open the door to friendship in every language, and Spanish speakers value polite, warm greetings.\n\nGreetings depend on the time of day. Buenos días means good morning, buenas tardes means good afternoon and buenas noches means good evening or good night. Hola means hello and is used any time. To ask how someone is, use ¿Cómo estás? with a friend or someone younger, and ¿Cómo está usted? with an older person or someone you respect. Spanish has two ways to say you. Tú is informal and used with friends, family and children. Usted is formal and used with elders, teachers, pastors and strangers. When in doubt, use usted.\n\nCommon answers include Estoy bien, gracias, which means I am fine, thank you, and Y tú? or ¿Y usted? which means and you? Other useful phrases are Mucho gusto, which means pleased to meet you, Por favor for please, Gracias for thank you, De nada for you are welcome, Perdón for excuse me or pardon me, Con permiso for excuse me when passing, and Lo siento for I am sorry.\n\nFarewells include Adiós for goodbye, Hasta luego for see you later, Hasta mañana for see you tomorrow and Nos vemos for we will see each other. A greeting is often accompanied by a handshake, and among family and friends a light kiss on the cheek is common in many Spanish speaking cultures.\n\nYour task: (1) Write a short greeting between you and a pastor using usted. (2) Write a short greeting with a friend using tú. (3) Explain when to use buenas tardes.\n\nFlorida standards: WL.912.", "video": "", "presenter": "Dr. Alex L. Jenkins Sr.", "standards": "WL.912", "script": "Welcome back. Listen, Proverbs 15:1 says, A soft answer turneth away wrath. Kind greetings open the door to friendship in every language.\n\nNow watch this. Buenos días is good morning. Buenas tardes is good afternoon. Buenas noches is good evening or good night. Hola is hello anytime.\n\nTo ask how someone is, say ¿Cómo estás? with a friend and ¿Cómo está usted? with an elder, a teacher or a pastor. Tú is informal and usted is formal. When in doubt, use usted.\n\nYou can answer Estoy bien, gracias. Mucho gusto means pleased to meet you. Por favor is please. De nada is you are welcome. Perdón and con permiso mean excuse me. Lo siento means I am sorry.\n\nTo say goodbye, use adiós, hasta luego or hasta mañana.\n\nYour task is to write two short greetings, one formal and one informal. Take the four question check. Excellence, Faith, Purpose. I will see you in the next lesson."}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'topic' and title = $j$1.2 Greetings, Farewells and Courtesy$j$);
  insert into public.course_items (course_id, kind, position, title, content) select cid, 'topic', 3, $j$1.3 Introducing Yourself, Countries and Nationalities$j$, $j${"readings": [{"title": "Acts 2 (King James Version)", "url": "/portal/bible/Acts/2"}], "body": "On the day of Pentecost the people were amazed because every man heard them speak in his own language, as Acts 2:6 records. Introducing yourself in someone's own language shows honor and love.\n\nTo say your name, use Me llamo and your name, which means my name is. To ask someone's name, say ¿Cómo te llamas? with a friend and ¿Cómo se llama usted? with someone you respect. To say where you are from, use Soy de, as in Soy de Florida. To ask, say ¿De dónde eres? Other helpful phrases are Tengo quince años for I am fifteen years old, and ¿Cuántos años tienes? for how old are you?\n\nThe verb ser means to be. Its present forms are yo soy, tú eres, él or ella or usted es, nosotros somos, and ellos or ellas or ustedes son. The subject pronouns are yo for I, tú for you, él for he, ella for she, usted for you formal, nosotros for we, ellos for they, ellas for they feminine, and ustedes for you all.\n\nCountries include Estados Unidos, México, Cuba, Puerto Rico, Colombia, la República Dominicana, Venezuela, Guatemala and España. Nationality words are adjectives that agree with the person. A man says Soy cubano and a woman says Soy cubana. A few end in e and stay the same, such as estadounidense for American. The word for American can also be norteamericano or norteamericana.\n\nYour task: (1) Write a four sentence introduction in Spanish giving your name, age, where you are from and nationality. (2) Conjugate ser for all subjects.\n\nFlorida standards: WL.912.", "video": "", "presenter": "Dr. Alex L. Jenkins Sr.", "standards": "WL.912", "script": "Welcome back. Listen, Acts 2:6 says every man heard them speak in his own language. When you introduce yourself in someone's language, you honor them.\n\nNow watch this. Me llamo means my name is. ¿Cómo te llamas? asks what is your name. Soy de means I am from. ¿De dónde eres? asks where are you from. Tengo quince años means I am fifteen years old.\n\nThe verb ser means to be. Yo soy. Tú eres. Él, ella, usted es. Nosotros somos. Ellos, ellas, ustedes son.\n\nNationalities are adjectives that match the person. A man says soy cubano. A woman says soy cubana. Estadounidense stays the same for both.\n\nYour task is to write a four sentence introduction and conjugate ser. Take the four question check. Excellence, Faith, Purpose. I will see you in the next lesson."}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'topic' and title = $j$1.3 Introducing Yourself, Countries and Nationalities$j$);
  insert into public.course_items (course_id, kind, position, title, content) select cid, 'topic', 4, $j$1.4 Numbers, Days, Months and Dates$j$, $j${"readings": [{"title": "Psalm 90 (King James Version)", "url": "/portal/bible/Psalms/90"}], "body": "Psalm 90:12 says, So teach us to number our days, that we may apply our hearts unto wisdom. Numbers, days and dates are part of every conversation.\n\nThe numbers from zero to ten are cero, uno, dos, tres, cuatro, cinco, seis, siete, ocho, nueve and diez. Eleven to fifteen are once, doce, trece, catorce and quince. Sixteen to nineteen are dieciséis, diecisiete, dieciocho and diecinueve. Twenty is veinte, and twenty one to twenty nine are veintiuno, veintidós, veintitrés and so on. The tens are treinta for 30, cuarenta for 40, cincuenta for 50, sesenta for 60, setenta for 70, ochenta for 80 and noventa for 90. From thirty onward the numbers are written as separate words joined by y, as in treinta y cinco for 35. One hundred is cien.\n\nThe days of the week are lunes for Monday, martes for Tuesday, miércoles for Wednesday, jueves for Thursday, viernes for Friday, sábado for Saturday and domingo for Sunday. On Spanish calendars the week often begins with Monday. Days and months are not capitalized in Spanish.\n\nThe months are enero, febrero, marzo, abril, mayo, junio, julio, agosto, septiembre, octubre, noviembre and diciembre. To give the date, say Hoy es el cinco de mayo, which means today is the fifth of May. The day comes before the month. To ask the date, say ¿Cuál es la fecha de hoy? To say your birthday, say Mi cumpleaños es el doce de octubre.\n\nYour task: (1) Write the numbers 1 to 20 in Spanish. (2) Write today's date in Spanish. (3) Write your birthday in Spanish.\n\nFlorida standards: WL.912.", "video": "", "presenter": "Dr. Alex L. Jenkins Sr.", "standards": "WL.912", "script": "Welcome back. Listen, Psalm 90:12 says, So teach us to number our days, that we may apply our hearts unto wisdom.\n\nNow watch this. Uno, dos, tres, cuatro, cinco, seis, siete, ocho, nueve, diez. Once, doce, trece, catorce, quince. Dieciséis, diecisiete, dieciocho, diecinueve, veinte.\n\nThe tens are treinta, cuarenta, cincuenta, sesenta, setenta, ochenta, noventa and cien. For 35, say treinta y cinco.\n\nThe days are lunes, martes, miércoles, jueves, viernes, sábado and domingo. The months are enero, febrero, marzo, abril, mayo, junio, julio, agosto, septiembre, octubre, noviembre and diciembre. Days and months are not capitalized.\n\nTo give the date, put the day first. Hoy es el cinco de mayo. Mi cumpleaños es el doce de octubre.\n\nYour task is to write numbers 1 to 20, today's date and your birthday. Take the four question check. Excellence, Faith, Purpose. I will see you in the next lesson."}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'topic' and title = $j$1.4 Numbers, Days, Months and Dates$j$);
  insert into public.course_items (course_id, kind, position, title, content) select cid, 'assessment', 1, $j$Assessment 1: Sounds, Greetings and Introductions$j$, $j${"prompt": "Write a report of at least 250 words in English with Spanish examples. Use complete sentences and label each part. Genesis 11:9 records that the LORD did confound the language of all the earth.\n\nPart 1: Explain how many letters the Spanish alphabet has, the sound of each vowel, and the sounds of h, j, ll, ñ and qu. Give an example word for each.\nPart 2: Write six greetings or courtesy phrases in Spanish with their English meaning, and explain when to use tú and when to use usted.\nPart 3: Write a short conversation in Spanish between two people meeting for the first time. Include names, where they are from, ages and a farewell.\nPart 4: Write the numbers 1 to 20, the days of the week and the months in Spanish, and write today's date in Spanish.\nPart 5: Explain how Proverbs 15:1 and Acts 2:6 guide you in greeting and honoring people who speak another language.", "rubric": "100 points. Part 1: 20 points. Part 2: 20 points. Part 3: 25 points. Part 4: 20 points. Part 5: 10 points. Complete sentences and conventions: 5 points. A score of 70 or above is passing."}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'assessment' and title = $j$Assessment 1: Sounds, Greetings and Introductions$j$);
  insert into public.course_items (course_id, kind, position, title, content) select cid, 'discussion', 1, $j$Discussion 1: Confound the Language, Bless the Neighbor$j$, $j${"prompt": "Write a post of at least 120 words that (1) describes a person or place near you where Spanish is spoken, (2) explains why greeting someone in their own language shows respect, (3) shares one phrase from this unit that you will use this week and who you will say it to, and (4) connects your answer to Genesis 11:9, Acts 2:6 or Proverbs 15:1. Then write a respectful reply of at least 40 words to another student's post, or answer this question: How does learning another language help the church serve its community? Keep your tone kind and respectful of other views."}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'discussion' and title = $j$Discussion 1: Confound the Language, Bless the Neighbor$j$);
  insert into public.course_items (course_id, kind, position, title, content) select cid, 'quiz', 1, $j$Check 1.1: The Spanish Alphabet and Pronunciation$j$, $j${"questions": [{"q": "How many letters are in the Spanish alphabet?", "options": ["30", "29", "27", "26"]}, {"q": "The letter h in Spanish is:", "options": ["Pronounced like s", "Pronounced like k", "Rolled", "Silent"]}, {"q": "The letter ñ sounds like:", "options": ["m in man", "ny in canyon", "l in love", "n in no"]}, {"q": "The vowel U in Spanish sounds like:", "options": ["uh in cup", "oh in go", "oo in food", "yoo in use"]}]}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Check 1.1: The Spanish Alphabet and Pronunciation$j$);
  insert into public.quiz_keys (item_id, answers, explains) select id, '{2,3,1,2}'::int[], array[$j$It has the 26 English letters plus ñ.$j$,$j$The h is always silent.$j$,$j$The ñ makes a ny sound.$j$,$j$Spanish vowels are always the same sound.$j$] from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Check 1.1: The Spanish Alphabet and Pronunciation$j$ on conflict (item_id) do nothing;
  insert into public.course_items (course_id, kind, position, title, content) select cid, 'quiz', 2, $j$Check 1.2: Greetings, Farewells and Courtesy$j$, $j${"questions": [{"q": "Buenos días means:", "options": ["Thank you", "Good night", "Goodbye", "Good morning"]}, {"q": "De nada means:", "options": ["Please", "You are welcome", "See you later", "I am sorry"]}, {"q": "Which form of you is formal?", "options": ["Tú", "Usted", "Nosotros", "Yo"]}, {"q": "Hasta mañana means:", "options": ["Pleased to meet you", "See you tomorrow", "Excuse me", "Good evening"]}]}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Check 1.2: Greetings, Farewells and Courtesy$j$);
  insert into public.quiz_keys (item_id, answers, explains) select id, '{3,1,1,1}'::int[], array[$j$Buenos días is a morning greeting.$j$,$j$De nada is the reply to gracias.$j$,$j$Usted shows respect.$j$,$j$Mañana means tomorrow.$j$] from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Check 1.2: Greetings, Farewells and Courtesy$j$ on conflict (item_id) do nothing;
  insert into public.course_items (course_id, kind, position, title, content) select cid, 'quiz', 3, $j$Check 1.3: Introducing Yourself, Countries and Nationalities$j$, $j${"questions": [{"q": "Me llamo means:", "options": ["I like", "I am tired", "My name is", "I am from"]}, {"q": "¿De dónde eres? asks:", "options": ["How are you?", "Where are you from?", "How old are you?", "What is your name?"]}, {"q": "The pronoun nosotros means:", "options": ["You all", "We", "I", "They"]}, {"q": "A woman from Mexico says:", "options": ["Son mexicana", "Soy mexicano", "Soy mexicana", "Eres mexicana"]}]}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Check 1.3: Introducing Yourself, Countries and Nationalities$j$);
  insert into public.quiz_keys (item_id, answers, explains) select id, '{2,1,1,2}'::int[], array[$j$Me llamo introduces your name.$j$,$j$De dónde means from where.$j$,$j$Nosotros is we.$j$,$j$Nationality adjectives agree with the speaker.$j$] from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Check 1.3: Introducing Yourself, Countries and Nationalities$j$ on conflict (item_id) do nothing;
  insert into public.course_items (course_id, kind, position, title, content) select cid, 'quiz', 4, $j$Check 1.4: Numbers, Days, Months and Dates$j$, $j${"questions": [{"q": "Quince is the number:", "options": ["14", "15", "5", "50"]}, {"q": "Martes is:", "options": ["March", "Tuesday", "Wednesday", "Monday"]}, {"q": "Enero is:", "options": ["January", "February", "June", "July"]}, {"q": "Cuarenta is:", "options": ["14", "4", "40", "400"]}]}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Check 1.4: Numbers, Days, Months and Dates$j$);
  insert into public.quiz_keys (item_id, answers, explains) select id, '{1,1,0,2}'::int[], array[$j$Quince means fifteen.$j$,$j$Martes is Tuesday.$j$,$j$Enero is the first month.$j$,$j$Cuarenta means forty.$j$] from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Check 1.4: Numbers, Days, Months and Dates$j$ on conflict (item_id) do nothing;
  insert into public.course_items (course_id, kind, position, title, content) select cid, 'quiz', 5, $j$Unit Quiz 1: Sounds, Greetings and Introductions$j$, $j${"questions": [{"q": "The Spanish vowel E sounds like:", "options": ["ay as in day", "ee", "eh", "uh"]}, {"q": "The word hola begins with a letter that is:", "options": ["Pronounced like k", "Silent", "Loud", "Rolled"]}, {"q": "Buenas tardes is used in the:", "options": ["Afternoon", "Late night only", "Morning only", "Morning"]}, {"q": "With a pastor you would ask how he is by saying:", "options": ["¿Cómo eres?", "¿Cómo son?", "¿Cómo estás?", "¿Cómo está usted?"]}, {"q": "Yo soy means:", "options": ["You are", "They are", "I am", "We are"]}, {"q": "Ella es cubana. The word cubana is feminine because:", "options": ["It follows a number", "Ella is a female", "It is a day", "It is a verb"]}, {"q": "Treinta y cinco is:", "options": ["35", "15", "30", "53"]}, {"q": "Jueves is:", "options": ["July", "Thursday", "Tuesday", "June"]}]}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Unit Quiz 1: Sounds, Greetings and Introductions$j$);
  insert into public.quiz_keys (item_id, answers, explains) select id, '{2,1,0,3,2,1,0,1}'::int[], array[$j$Spanish E is eh.$j$,$j$The h is silent.$j$,$j$Tarde means afternoon.$j$,$j$Usted is the respectful form.$j$,$j$Yo is I and soy is am.$j$,$j$Adjectives agree with the person described.$j$,$j$Treinta is 30 and cinco is 5.$j$,$j$Jueves is Thursday.$j$] from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Unit Quiz 1: Sounds, Greetings and Introductions$j$ on conflict (item_id) do nothing;
